    \includegraphics[width=10.625cm]{ArcResHorDiff.pdf}
    \caption{$n$ elements in the image of $d_{h}(A_{n})$, where $A_{n}\in Arc_{n-1}\big(C_{n}(\ensuremath{\mathbb{R}}^{2})\big)$.
    Viewing $A_{n}$ as a class in $H_{0}\Big(Arc_{n-1}\big(C_{n}(\ensuremath{\mathbb{R}}^{2})\big)\Big)$, this is its image under the $d^{1}$-differential.}
    \label{ArcResHorDiff}
\end{figure}

The maps induced by $\overline{e}$ make the chains and the homology of $Arc_{*}\big(C_{\bullet}(\ensuremath{\mathbb{R}}^{2})\big)$ into a differential graded algebra.
We call this the \emph{arc resolution algebra}, and we write $a$ for the generator of $H_{0}\Big(Arc_{0}\big(C_{1}(\ensuremath{\mathbb{R}}^{2})\big)\Big)$ and $pt$ for the generator of $H_{0}\Big(Arc_{-1}\big(C_{1}(\ensuremath{\mathbb{R}}^{2})\big)\Big)=H_{0}\big(C_{1}(\ensuremath{\mathbb{R}}^{2})\big)$.
Taking the tensor product of $n$ arcs $a$, yields $A_{n}$, the generator of  $H_{0}\Big(Arc_{n-1}\big(C_{n}(\ensuremath{\mathbb{R}}^{2})\big)\Big)$.

Given $X\in H_{0}\Big(Arc_{-1}\big(C_{n}(\ensuremath{\mathbb{R}}^{2})\big)\Big)$ and $Y\in H_{0}\Big(Arc_{p}\big(C_{n}(\ensuremath{\mathbb{R}}^{2})\big)\Big)$, we define the \emph{twist}, $\psi(X,Y)$ to be the classes depicted in Figures~\ref{PureTwists} and \ref{MixedTwists}, and we recursively define the \emph{$l$-pure twists} by 
\[
P_{0}:=pt \text{ and } P_{l}:=\psi(P_{l-1}, P_{l_1});
\]
see Figure~\ref{PureTwists}.
