    \caption{The pure twists $P_{0}$, $P_{1}$, and $P_{2}$.}
    \label{PureTwists}
\end{figure}.
Similarly, we define an \emph{$(l+1)$-mixed twist} by
\[
M_{l+1}:=\psi(P_{l}, A_{2^{l}});
\]
see Figure~\ref{MixedTwists}.
\begin{figure}[H]
    \centering
    \includegraphics[width=5.625cm]{MixedTwists.pdf}
    \caption{The mixed twists $M_{1}$ and $M_{2}$.}
    \label{MixedTwists}
